// Üretilen dosya: tool/ozgun/uret.py. Coğrafya · Türkiye bölgeleri: Karadeniz, Marmara, Ege, Akdeniz, İç, Doğu ve Güneydoğu Anadolu ayrıntıları (kolay).
const ozGeography14Kolay = <(String, String, List<String>, String)>[
  ('Türkiye\'de çay tarımının Rize ve çevresinde yoğunlaşmasında hangi iklim özelliği belirleyicidir?', 'Yıl boyunca yağış alan nemli ve ılık iklim', ['Yazları kurak geçen ılık iklim', 'Kışları çok soğuk, karasal iklim', 'Düşük nemli ve rüzgârlı step iklimi'], 'Çay bitkisi her mevsim yağış ve yüksek nem ister. Doğu Karadeniz kıyıları bu koşulları sağladığı için çay burada yetişir.'),
  ('Karadeniz kıyısındaki Zonguldak\'ın Türkiye ekonomisindeki ayırt edici önemi hangi kaynakla ilgilidir?', 'Taş kömürü', ['Linyit', 'Bor tuzları', 'Krom'], 'Zonguldak havzası Türkiye\'nin taş kömürü yatağıdır. Taş kömürü çıkarıldığı bölge burasıdır.'),
  ('Karadeniz Bölgesi\'ndeki Çarşamba Ovası hangi akarsuyun deltasıdır?', 'Yeşilırmak', ['Kızılırmak', 'Sakarya', 'Filyos'], 'Çarşamba Ovası Yeşilırmak deltasında oluşmuştur. Bafra Ovası ise Kızılırmak deltasıdır.'),
  ('Karadeniz Bölgesi\'nde ormanların bölge yüzölçümünün büyük bölümünü kaplamasının temel nedeni nedir?', 'Bol ve düzenli yağış', ['Toprağın çok tuzlu olması', 'Karasal iklimin etkisi', 'Yazın kuraklığın uzun sürmesi'], 'Her mevsim yağış nemli koşullar yaratır; bu da geniş orman örtüsünün gelişmesini sağlar.'),
  ('Karadeniz Bölgesi\'nde yayla turizmi ve yayla şenlikleri en çok hangi çevrede gelişmiştir?', 'Rize ve Trabzon yaylaları', ['Konya Ovası', 'Çukurova', 'Ergene Havzası'], 'Doğu Karadeniz\'in yüksek kesimlerindeki Ayder, Pokut gibi yaylalar yaz aylarında hem hayvancılık hem turizm merkezidir.'),
  ('Karadeniz kıyılarında doğal liman sayısının azlığının başlıca nedeni nedir?', 'Kıyı çizgisinin az girintili çıkıntılı olması', ['Denizin çok sığ olması', 'Gel-git olayı', 'Akarsuların çok az olması'], 'Kıyıya paralel uzanan dağlar kıyı çizgisini düzgün tutar; bu nedenle doğal korunaklı koy ve liman azdır.'),
  ('Aşağıdaki illerden hangisi Karadeniz Bölgesi\'nde değildir?', 'Kırşehir', ['Tokat', 'Bolu', 'Gümüşhane'], 'Kırşehir İç Anadolu\'dadır. Diğerleri Karadeniz Bölgesi\'ndedir.'),
  ('Karadeniz\'in kıyı yerleşmelerinde evlerin ahşap ve çatılarının eğimli yapılmasının temel nedeni nedir?', 'Bol yağış ve orman', ['Çok yüksek sıcaklık', 'Kuraklık', 'Depremsizlik'], 'Bol yağış çatıları eğimli kılar; yaygın orman da ahşabı bol bir yapı malzemesi yapar.'),
  ('Marmara Bölgesi\'nde nüfus yoğunluğunun Türkiye ortalamasının çok üzerinde olmasının temel nedeni hangisidir?', 'Sanayi ve hizmet sektörünün yoğunluğu nedeniyle sürekli göç alması', ['Tarım arazilerinin çok engebeli olması', 'Madencilik faaliyetlerinin azlığı', 'Enerji kaynaklarının bolluğu'], 'Sanayi, ticaret ve istihdam imkânları Marmara\'ya sürekli iç göç çekmiştir. Bu da nüfus yoğunluğunu artırmıştır.'),
  ('Marmara Bölgesi\'nde Uludağ\'ın zirve kuşağında kış turizminin gelişmesinin temel doğal nedeni nedir?', 'Kar örtüsünün uzun süre kalması', ['Hiç yağış olmaması', 'Sıcaklığın yüksek olması', 'Akarsuların çokluğu'], 'Uludağ yüksek olduğundan kış aylarında bol kar yağar ve kar örtüsü uzun süre kalır. Kayak turizmine elverişlidir.'),
  ('Trakya\'da Edirne\'nin Bulgaristan ve Yunanistan sınır kapısı olması coğrafi olarak neyi sağlar?', 'Avrupa\'ya karayolu ve demiryolu geçişi sağlar', ['Akdeniz\'e doğrudan çıkış', 'Hindistan\'a doğrudan geçiş', 'Deniz ticaretinin tamamen bitmesi'], 'Edirne, Türkiye\'nin Avrupa\'ya açılan karayolu ve demiryolu kapısıdır; Kapıkule bu amaçla önemlidir.'),
  ('Aşağıdakilerden hangisi Marmara Bölgesi\'nin tarımsal ürün karakteri için doğrudur?', 'Ayçiçeği, çeltik ve şeftali gibi ürünlerin yanında sanayi bitkileri de yetişir', ['Çay ve muz üretimi yapılır', 'Haşhaş ve incir en çok burada yetişir', 'Antep fıstığı ve kayısı üretilir'], 'Marmara\'da Trakya\'da ayçiçeği, Edirne\'de çeltik ve Bursa\'da şeftali gibi çeşitli ürünler yetişir.'),
  ('Aydın ve çevresinde incir üretiminin yoğun olması hangi iklim özelliğiyle açıklanır?', 'Uzun, sıcak ve kurak yazlar ile ılık kışlar', ['Soğuk ve karlı kışlar', 'Her mevsim bol yağış', 'Çok düşük yıllık sıcaklık ortalaması'], 'İncir kuraklığa dayanıklı, sıcak seven bir bitkidir. Büyük Menderes Havzası\'nın Akdeniz iklimi onun için uygundur.'),
  ('Kütahya, Afyon ve Uşak çevresinde Ege kıyısına göre kışların daha soğuk geçmesinin nedeni nedir?', 'Yükselti artışı ve denizden uzaklaşma', ['Enlem farkı', 'Akıntılar', 'Rüzgâr yönünün hiç değişmemesi'], 'Ege\'nin iç kesimi yüksek platolardan oluşur; denizden uzaklaşma ve yükselti nedeniyle karasal özellikler artar.'),
  ('Denizli\'nin tekstil sanayisi merkezlerinden biri olmasında etkili bir tarım ürünü hangisidir?', 'Pamuk', ['Çay', 'Fındık', 'Şeker kamışı'], 'Büyük Menderes Havzası\'nda pamuk yetişir. Denizli\'de bu hammadde ile havlu ve bornoz gibi dokuma sanayisi gelişmiştir.'),
  ('Çeşme Yarımadası\'nda Alaçatı\'nın rüzgâr sörfü için ünlü olmasının doğal nedeni nedir?', 'Etezyen rüzgârlarının düzenli esmesi', ['Dalgaların hiç olmaması', 'Gel-git olayı', 'Sürekli kar yağışı'], 'Alaçatı koyu, yaz aylarında düzenli esen meltem rüzgârları sayesinde rüzgâr sörfü ve uçurtma sörfü için uygundur.'),
  ('Dalaman Ovası ve çevresinde hangi mevsimlik turizm hareketi dikkat çeker?', 'Yaz tatili ve sahil turizmi', ['Kış sporları', 'Maden turizmi', 'Av turizmi'], 'Dalaman, Fethiye ve Marmaris çevresi Akdeniz iklimi nedeniyle yaz sezonunda yoğun sahil turizmi alır.'),
  ('Yörüklerin yazın yaylalara, kışın kıyıya inmesi geleneği Akdeniz\'de hangi göç türüne örnektir?', 'Mevsimlik hayvancılık göçü', ['Zorunlu göç', 'Beyin göçü', 'Dış göç'], 'Yörükler, sürüleriyle kışın ılık kıyı ovasına, yazın serin yaylalara çıkar. Bu, mevsime bağlı hayvancılık göçüdür.'),
  ('Mersin Limanı\'nın Türkiye için önemi hangisinden kaynaklanır?', 'Akdeniz\'e açılan büyük ticaret ve konteyner limanı olması', ['Karadeniz\'in en büyük limanı olması', 'Baraj gölünde bulunması', 'Fiyort kıyılarında yer alması'], 'Mersin, Çukurova ve İç Anadolu\'ya demir ve karayoluyla bağlanan bir hinterlanda sahiptir. Akdeniz\'in önemli limanlarındandır.'),
  ('Antalya Körfezi\'ndeki Konyaaltı ve Lara plajlarının kentin ekonomik yapısına katkısı nedir?', 'Turizm gelirlerini artırması', ['Madencilikte verim artışı', 'Tarımda tuzlanma', 'Balıkçılığın artması'], 'Antalya\'nın kum ve çakıl plajları ile ılıman iklimi turizmi kentin ana gelir kaynaklarından biri yapmıştır.'),
  ('Doğu Anadolu\'da kışın hava sıcaklığının çok düşmesinin başlıca nedenleri arasında hangisi yer almaz?', 'Denize çok yakın olması', ['Yükseltinin fazla olması', 'Karasal iklimin etkisi', 'Kuzey yönlü soğuk hava kütleleri'], 'Doğu Anadolu yüksek ve denizden uzaktır. Bu nedenle kışları çok soğuk, yazları kısa ve serindir; denize yakın olma durumu bu bölgeye uymaz.'),
  ('Erzurum ve Kars gibi illerde kış turizminin gelişmesini sağlayan başlıca iklim özelliği nedir?', 'Kar örtüsünün uzun süre kalması', ['Yazları çok nemli olması', 'Kışları ılık geçmesi', 'Yağışın çok az olması'], 'Uzun süre kalan kar, kayak sezonunu uzatır. Palandöken ve Sarıkamış gibi merkezler bundan yararlanır.'),
  ('Doğu Anadolu\'da tarım alanlarının sınırlı olmasının temel nedeni hangisidir?', 'Yükselti fazlalığı nedeniyle vejetasyon süresinin kısa olması', ['Aşırı sıcaklık', 'Çok fazla bataklık olması', 'Sürekli yağış'], 'Soğuk ve kısa yaz dönemi, ürün çeşidini ve verimi sınırlar. Bu yüzden hayvancılık ön plandadır.'),
  ('Kars\'ta peynir ve kaşar üretiminin yaygın olması hangi doğal kaynağa bağlıdır?', 'Geniş meralar ve yaylaların bulunması', ['Çay bahçeleri', 'Pamuk tarlaları', 'Zeytinlikler'], 'Kars çevresindeki zengin otlaklar süt hayvancılığını destekler. Bu da peynir sanayisini geliştirir.'),
  ('Doğu Anadolu\'da yaylacılığın hayvancılık için önemi nedir?', 'Yaz otlaklarını kullanarak yem maliyetini düşürmesi', ['Kışın ürün yetiştirmeyi sağlaması', 'Balıkçılığı geliştirmesi', 'Madencilikte verimi artırması'], 'Kısa yaz mevsiminde yüksek mera bitkileri hayvanları besler. Kışın ise hayvanlar ahırda beslenir.'),
  ('Güneydoğu Anadolu\'da yaz sıcaklıklarının çok yüksek olmasının nedeni aşağıdakilerden hangisidir?', 'Güneyde ve alçakta olması, Arap Çölü\'nden etkilenmesi', ['Karadeniz\'e yakın olması', 'Çok yüksek dağlarla çevrili olması', 'Yağış fazlalığı'], 'Bölge Suriye çöllerinin sıcak havasına açıktır ve alçak olduğundan yaz çok sıcak geçer.'),
  ('Karacadağ\'ın lav örtüsünün oluşturduğu karakteristik tarım ürünü olarak Diyarbakır\'ın hangi ürünü ünlüdür?', 'Karpuz', ['Fındık', 'Çay', 'Muz'], 'Diyarbakır karpuzu Dicle çevresindeki sulak ve verimli topraklarda yetişir; kentin simge ürünüdür.'),
  ('Güneydoğu Anadolu\'da hayvancılığın en yaygın olduğu çeşit olarak hangisi gösterilir?', 'Koyun ve keçi', ['Manda', 'Deve', 'Domuz'], 'Bölgede otlak alanlar yaygındır; küçükbaş hayvancılık (koyun ve keçi) en yaygın olanıdır.'),
  ('GAP projesi sonrasında Güneydoğu\'da pamuk üretiminin artması hangi sanayi koluna ham madde sağlamıştır?', 'Tekstil sanayisine', ['Demir-çelik sanayisine', 'Gemi inşaya', 'Çay işletmeciliğine'], 'Pamuk, iplik ve dokuma sanayisinin hammaddesidir. Gaziantep, Şanlıurfa gibi kentlerde tekstil gelişmiştir.'),
  ('Güneydoğu Anadolu Bölgesi\'nin yüzölçümü açısından Türkiye bölgeleri arasındaki yeri hakkında doğru bilgi hangisidir?', 'En küçük bölgelerdendir', ['En büyük bölgedir', 'Marmara ile aynı büyüklüktedir', 'Karadeniz\'den büyüktür'], 'Güneydoğu Anadolu, yüzölçümü bakımından Türkiye\'nin en küçük coğrafi bölgesidir.'),
  ('Çarşamba ve Bafra ovalarının tarıma elverişli olmasının temel nedeni nedir?', 'Alüvyonlu verimli delta toprağı', ['Volkanik kül örtüsünün kalınlığı', 'Soğuk ve kuru karasal iklim', 'Buzul çökellerinin varlığı'], 'Bu ovalar Yeşilırmak ve Kızılırmak deltalarında oluşmuştur; akarsuların taşıdığı alüvyon toprakları çok verimlidir.'),
  ('Ilgaz Dağları\'nda kış turizminin gelişmesini sağlayan doğal etken nedir?', 'Uzun süre kalan kar örtüsü', ['Kışların çok sıcak ve kuru geçmesi', 'Okyanus akıntılarının ılıman etkisi', 'Çölleşme ve kuraklığın hakimiyeti'], 'Ilgaz\'da kış yağışları kar biçiminde olur ve örtü uzun süre kalır. Kayak merkezleri bu nedenle kurulmuştur.'),
  ('Küre ve Köroğlu dağlarının orman zenginliği hangi sanayi koluna katkı sağlar?', 'Orman ürünleri ve mobilya', ['Bor işleme ve cam sanayisi', 'Çimento ve seramik sanayisi', 'Petrokimya ve gübre sanayisi'], 'Zengin ormanlar odun, kereste ve kâğıt hamuru gibi ham maddeleri sağlayarak orman ürünleri sanayisini destekler.'),
  ('Ordu\'daki Perşembe Yaylası\'nın turizm açısından önemi nedir?', 'Serin yayla havası ve manzara', ['Uzun ve sıcak deniz kumsalı', 'Kış sporları ve kayak pistleri', 'Maden turizmi ve kaya tırmanışı'], 'Perşembe Yaylası yaz aylarında serin havası, ormanı ve manzarasıyla ziyaretçi çeker.'),
  ('Aşağıdakilerden hangisi Doğu Anadolu Bölgesi\'nde bulunan bir ildir?', 'Bingöl', ['Kilis', 'Kırşehir', 'Kastamonu'], 'Bingöl Doğu Anadolu\'dadır. Kilis Güneydoğu Anadolu\'da, Kırşehir İç Anadolu\'da, Kastamonu Karadeniz\'dedir.'),
  ('Aşağıdaki ürün-bölge eşleşmelerinden hangisi yanlıştır?', 'Çay - Güneydoğu Anadolu', ['Fındık - Karadeniz', 'Zeytin - Ege', 'Antep fıstığı - Güneydoğu Anadolu'], 'Çay yalnızca Doğu Karadeniz\'de yetişir. Güneydoğu Anadolu\'da çay yetiştirilmez.'),
  ('Yağış bakımından Türkiye\'de en yağışlı bölge hangisidir?', 'Karadeniz', ['Marmara', 'İç Anadolu', 'Güneydoğu Anadolu'], 'Karadeniz Bölgesi, nemli rüzgârların dağlara çarpması ve yıl boyu yağış alması nedeniyle Türkiye\'nin en çok yağış alan bölgesidir.'),
  ('Türkiye\'de turizm gelirlerinin yoğunlaştığı kıyı bölgeleri hangisinde doğru verilmiştir?', 'Akdeniz ve Ege kıyıları', ['Doğu Karadeniz ve Doğu Anadolu', 'İç Anadolu ve Güneydoğu', 'Kuzey Marmara ve Doğu Anadolu'], 'Akdeniz ve Ege kıyıları, uzun güneşli yaz sezonu ve sahilleriyle Türkiye\'nin en önemli sahil turizm merkezleridir.'),
  ('Abant Gölü\'nün Bolu Dağı eteklerinde ormanlarla çevrili bir yerde bulunması hangi turizm türüne elverişlidir?', 'Doğa ve doğa yürüyüşü turizmine', ['Kış sporlarına yoğun kar olmadan', 'Çöl safarisine', 'Sıcak su sporlarına'], 'Abant, yoğun ormanlarla çevrili bir göldür; yürüyüş, kamp ve doğa turizmi için tercih edilir.'),
  ('Bursa\'daki İznik Gölü\'nün çevresinde yer alan, çini sanatıyla bilinen yerleşmenin adı hangisidir?', 'İznik', ['Gemlik', 'Yenişehir', 'Mustafakemalpaşa'], 'İznik, aynı adı taşıyan gölün kıyısında kurulmuştur; tarihte çini ve seramik üretimiyle ünlüdür.'),
  ('İstanbul\'un Büyükada ile birlikte anılan Prens Adaları hangi denizde yer alır?', 'Marmara Denizi', ['Karadeniz\'in batı kıyısı açıklarındaki sular', 'Ege Denizi', 'Akdeniz'], 'Adalar, İstanbul\'un güneydoğusunda Marmara Denizi\'nde yer alır; Büyükada, Heybeliada, Burgazada ve Kınalıada başlıcalarıdır.'),
  ('Bursa Ovası\'nda Nilüfer Çayı\'nın taşıdığı alüvyonlar hangi tarım ürününün yetişmesini kolaylaştırır?', 'Şeftali ve sebze', ['Kuru fasulye ve nohut ile birlikte arpa', 'Muz', 'Haşhaş'], 'Bursa Ovası, Nilüfer Çayı alüvyonlarıyla verimlidir. Meyve ve sebze üretimi yaygındır.'),
  ('Yalova\'daki Termal ilçesinin turizm açısından önemi hangi kaynağa dayanır?', 'Sıcak su kaynakları', ['Sıcak çöl iklimi ve kuraklık nedeniyle', 'Tuz gölleri', 'Volkanik kalderalar'], 'Termal, doğal sıcak su kaynaklarıyla bilinen bir kaplıca merkezidir.'),
  ('Çanakkale\'nin Bozcaada\'sında yetişen ve adaya ün kazandıran ürün hangisidir?', 'Üzüm ve şarap', ['Kayısı ve incir üretimi ile ünlü olması', 'Fındık', 'Muz'], 'Bozcaada, bağcılığı ve şaraplarıyla bilinir; küçük adanın ekonomisi turizm ve bağcılığa dayanır.'),
  ('Aydın\'ın Söke Ovası\'nda yaygın olarak yetiştirilen ürün hangisidir?', 'Pamuk', ['Çay', 'Fındık', 'Haşhaş'], 'Söke Ovası, Büyük Menderes\'in taşıdığı alüvyonlarla verimlidir; pamuk bu ovanın başlıca ürünüdür.'),
  ('Manavgat Şelalesi\'nin üzerinde bulunduğu akarsu hangisidir?', 'Manavgat Çayı', ['Aksu Çayı', 'Eşen Çayı', 'Dalaman Çayı'], 'Manavgat Şelalesi, Antalya\'da Manavgat Çayı üzerindedir; şelale Side yakınındadır.'),
  ('Antalya\'nın Kumluca ilçesi Türkiye\'de hangi tarım biçimiyle bilinir?', 'Sera tarımı', ['Çay tarımı', 'Pirinç tarımı', 'Tütün tarımı'], 'Kumluca ve çevresi seralarda domates, biber ve salatalık gibi ürünlerle Türkiye\'nin sera üretim merkezlerindendir.'),
  ('Seyhan Barajı\'nın Adana\'daki işlevleri arasında en çok hangisi öne çıkar?', 'Sulama, enerji ve taşkın kontrolü', ['Tuz ve maden işleme tesislerinin ihtiyacı için', 'Balıkçılık ihracatı', 'Petrol depolama'], 'Seyhan Barajı, Çukurova\'yı sular, elektrik üretir ve taşkın riskini azaltır.'),
  ('Bingöl\'ün Genç ilçesinde ve Solhan yöresinde fay hattı üzerinde sık görülen doğal olay hangisidir?', 'Deprem', ['Çığ', 'Tsunami', 'Kuraklık'], 'Doğu Anadolu Fay Hattı bu bölgeden geçer; bu nedenle depremler sık görülür.'),
  ('Şanlıurfa\'daki Balıklıgöl çevresi hangi tarihî yerleşmenin merkezidir?', 'Urfa kent merkezi', ['Karadeniz kıyısındaki bir liman kenti merkezi', 'Ege kıyısındaki bir antik kentin merkezi', 'Akdeniz kıyısındaki bir kale kentin merkezi'], 'Balıklıgöl, Şanlıurfa\'nın tarihî merkezinde yer alır ve inanç turizmi açısından önemli bir havuz ve park alanıdır.'),
  ('Mardin\'in Kızıltepe ilçesi hangi sınır komşusuna yakındır?', 'Suriye', ['Gürcistan sınırındaki kıyı bölgesine', 'Yunanistan sınırındaki kıyıya', 'Bulgaristan sınırındaki dağlık bölgeye'], 'Kızıltepe, Mardin\'in güneyinde, Suriye sınırına yakın bir ova ilçesidir.'),
  ('Bir öğrenci Karadeniz Bölgesi\'ni anlatırken dört cümle kuruyor. Bu cümlelerden hangisi bölgenin gerçeğine uymamaktadır?', 'Kıyıya dik uzanan dağlar nedeniyle kıyı çizgisi çok girintili çıkıntılıdır.', ['Doğu Karadeniz\'de çay ve fındık tarımı kıyı kuşağında yoğundur.', 'Zonguldak çevresi Türkiye\'nin taş kömürü havzasını oluşturur.', 'Kuzey Anadolu Dağları kıyıya paralel uzandığı için iç kesimlere ulaşım sınırlıdır.'], 'Karadeniz kıyısında dağlar kıyıya paralel uzanır ve kıyı düzdür. Girintili çıkıntılı kıyı Ege\'nin özelliğidir.'),
  ('Marmara Bölgesi\'nin doğal ve beşerî özellikleri sıralanıyor. Hangi ifade bölgeye uymayan bir bilgi içerir?', 'Bölgede kar yağışı ve don olayı hiç görülmez, bitki örtüsü yalnız makidir.', ['Bölgenin yüzölçümü küçük olduğu hâlde nüfusu fazladır.', 'Geçiş iklimi yaşandığı için ürün çeşitliliği fazladır.', 'Bölgede Boğazlar Karadeniz ile Akdeniz arasındaki su yolunu oluşturur.'], 'Marmara\'da kış aylarında kar ve don görülür; Trakya ve yüksek kesimlerde orman da vardır. Bitki örtüsü yalnız maki değildir.'),
  ('Ege Bölgesi hakkında öğretmen dört ifade yazıyor. Bunlardan hangisi hatalıdır?', 'Bölge, Türkiye\'de en çok yağış alan ve her mevsim yağışlı olan bölgedir.', ['Zeytin, incir ve üzüm bölgenin tipik tarım ürünleri arasındadır.', 'Kıyı Ege\'de dağlar denize dik uzanır ve kıyı girintili çıkıntılıdır.', 'Gediz ve Büyük Menderes çöküntü ovalarında akar.'], 'Türkiye\'nin en yağışlı bölgesi Karadeniz\'dir. Ege\'de yağış kışın ve ilkbaharda düşer, yazlar kuraktır.'),
  ('İç Anadolu Bölgesi\'nin özelliklerini sayan bir metindeki cümlelerden hangisi yanlış bilgi içerir?', 'Bölgede nüfus en çok kıyı kuşağında, denize yakın yerlerde toplanmıştır.', ['Bölgede step bitki örtüsü geniş alan kaplar.', 'Çevresi dağlarla çevrili olduğundan yağış az, iklim karasaldır.', 'Tuz Gölü, bölgenin en bilinen kapalı havzasıdır.'], 'İç Anadolu\'nun denize kıyısı yoktur. Nüfus büyük kentlerde ve ova kenarlarında toplanır.'),
  ('Doğu Anadolu\'yu anlatan bir sunumdaki ifadelerden hangisi gerçeği yansıtmaz?', 'Bölgede turunçgil ve muz tarımı yaygın biçimde yapılır.', ['Ortalama yükseltisi en fazla olan bölgedir.', 'Türkiye\'nin en yüksek dağı Ağrı bu bölgededir.', 'Kışlar uzun ve çok soğuk, yazlar kısa ve serindir.'], 'Doğu Anadolu soğuk iklimli, yüksek bir bölgedir; turunçgil ve muz sıcak-ılık kıyıların ürünleridir.'),
  ('Aşağıdakilerden hangisi Ege Bölgesi\'nde turizmin gelişmesinde etkili değildir?', 'Yıl boyu karla örtülü yüksek dağlar', ['Girintili çıkıntılı kıyılar ve koylar', 'Tarihî ve arkeolojik zenginlikler', 'Uzun, sıcak ve güneşli yaz mevsimi'], 'Ege\'de yıl boyu karla örtülü dağlar yoktur. Turizm koylar, antik kentler ve güneşli yaz sayesinde gelişmiştir.'),
  ('Aşağıdakilerden hangisi GAP\'ın sağladığı sonuçlardan biri değildir?', 'Çay ve fındık üretiminin artması', ['Sulanan alanların genişlemesi', 'Elektrik üretiminin artması', 'Tarıma dayalı sanayinin gelişmesi'], 'GAP, Fırat-Dicle havzasında sulama ve enerji projesidir. Çay ve fındık Karadeniz ürünleridir; GAP\'la ilgisi yoktur.'),
  ('Aşağıdaki akarsu ve döküldüğü deniz eşleşmelerinden hangisi yanlıştır?', 'Sakarya - Marmara Denizi', ['Seyhan - Akdeniz', 'Gediz - Ege Denizi', 'Yeşilırmak - Karadeniz'], 'Sakarya Nehri Karadeniz\'e dökülür; Marmara\'ya değil. Diğer eşleşmeler doğrudur.'),
  ('Bir tarım mühendisi yazın kurak, kışın ılık ve yağışlı bir yerde zeytin bahçesi kurmayı düşünüyor. Hangi kıyı seçilmelidir?', 'Ege kıyıları', ['Doğu Karadeniz kıyısı', 'Doğu Anadolu\'nun Erzurum-Kars çevresi platosu', 'Güneydoğu\'nun Mardin-Cizre çevresi ovası'], 'Zeytin, Akdeniz iklimi koşullarında yetişir; yazı kurak, kışı ılık ve yağışlı olan Ege kıyıları bu koşulları sağlar.'),
  ('Bir girişimci muz yetiştirmek için yazı sıcak, kışı donsuz bir kıyı arıyor. Aşağıdakilerden hangisi uygundur?', 'Alanya-Anamur kıyı şeridi', ['Giresun-Ordu fındık kıyı şeridi', 'Edirne-Kırklareli Trakya şeridi', 'Erzurum-Kars yayla şeridi'], 'Muz don olayına çok duyarlıdır. Alanya-Anamur kıyısı kışın donsuz geçtiği için muz yetiştirilen yerdir.'),
  ('Bir meteoroloji öğrencisi bir istasyonda yağışın yıl boyu düzenli ve yüksek olduğunu görüyor. İstasyon büyük olasılıkla hangi kıyıdadır?', 'Doğu Karadeniz', ['Kıyı Ege', 'Akdeniz', 'Güneydoğu Anadolu'], 'Her mevsim yağışlı olan nemli iklim Doğu Karadeniz\'e özgüdür; diğerlerinde yazlar belirgin kuraktır.'),
  ('Bir ziraat mühendisi kuru tarım yapılan, yağışı az, yazı sıcak ve kurak, kışı soğuk bir yerde buğday ve arpa öneriyor. Bu yer hangi bölgedir?', 'İç Anadolu', ['Doğu Karadeniz', 'Kıyı Ege', 'Antalya kıyısı'], 'İç Anadolu\'nun karasal ve az yağışlı koşulları buğday ve arpa gibi tahılların kuru tarımına uygundur.'),
  ('Bir araştırmacı, bir kıyıda dağların denize paralel uzandığı, kıyının düz olduğunu ve nemli iklim görüldüğünü saptıyor. Bu kıyı hangisidir?', 'Karadeniz kıyısı', ['Ege kıyısı', 'Marmara\'nın güney kıyısı', 'Akdeniz\'in Antalya kıyısı'], 'Karadeniz\'de dağlar kıyıya paralel uzandığı için kıyı düzdür ve nemli iklim görülür.'),
  ('Bir ziraat öğrencisi Antep fıstığının en çok üretildiği bölgeyi arıyor. Bu bölge hangisidir?', 'Güneydoğu Anadolu', ['Doğu Karadeniz\'in Rize-Trabzon çevresi', 'Kıyı Ege\'nin İzmir çevresi', 'Marmara\'nın Edirne çevresi'], 'Antep fıstığı kurak ve sıcak yazlara dayanıklıdır; Güneydoğu\'nun Gaziantep, Şanlıurfa ve Siirt çevresi üretim merkezidir.'),
  ('Fındık ağaçları, hamsi, Boztepe ve Perşembe Yaylası ile bilinen, Doğu Karadeniz\'deki ilimiz hangisidir?', 'Ordu', ['Kırşehir', 'Kırıkkale', 'Kütahya'], 'Ordu, Karadeniz kıyısında fındık üretimi, Boztepe ve Perşembe Yaylası ile tanınır.'),
  ('Sakız Adası\'na bakan yarımada, Alaçatı, Ilıca ve kaplıcalarıyla ünlü yer hangisidir?', 'Çeşme', ['Çanakkale', 'Çorlu', 'Çarşamba'], 'Çeşme, İzmir\'in batı ucundaki yarımadada yer alır; Alaçatı ve Ilıca gibi yerleri vardır.'),
  ('Çukurova\'da Seyhan Nehri kıyısında kurulu, tarihî Taşköprü ve Sabancı Merkez Camii ile bilinen il hangisidir?', 'Adana', ['Aydın', 'Ardahan', 'Amasya'], 'Adana, Çukurova\'nın merkezidir; Taşköprü ve Seyhan Nehri kent kimliğinin parçalarıdır.'),
  ('Haliç, Kapalıçarşı ve iki yakayı bağlayan köprülerle bilinen, Marmara\'nın en kalabalık ili hangisidir?', 'İstanbul', ['İzmir', 'İçel/Mersin', 'Isparta'], 'İstanbul, Marmara Bölgesi\'nin ve Türkiye\'nin en kalabalık ilidir; Haliç ve Boğaz köprüleri kentin simgelerindendir.'),
  ('Aşağıdaki bölgelerden hangisi il sayısı bakımından en fazla ile sahiptir?', 'Karadeniz Bölgesi', ['Doğu Anadolu Bölgesi, yüzölçümü en büyük olan bölge', 'Marmara Bölgesi, nüfusu en fazla olan bölge', 'İç Anadolu Bölgesi, başkentin yer aldığı bölge'], 'Karadeniz Bölgesi 18 il ile en fazla ile sahip bölgedir. Doğu Anadolu\'da 14, İç Anadolu\'da 13 il bulunur.'),
  ('Ege\'de Gediz ve Büyük Menderes ovalarındaki sulu tarımın yaz mevsiminde su ihtiyacının artması hangi iklim özelliğinden kaynaklanır?', 'Yazların sıcak ve kurak geçmesi', ['Yazın yağışın bol olması', 'Kışların çok soğuk geçmesi', 'Yaz sisleri ve nemli hava'], 'Akdeniz iklimi yazları kuraktır. Bitkilerin su ihtiyacı arttığında yağış azdır; bu nedenle sulama gerekir.'),
  ('Doğu Anadolu\'da yaz sonunda hayvanların yaylalardan köylere indirilmesinin temel nedeni nedir?', 'Soğuk başlar, otlaklar kar altında kalır', ['Yaz sıcaklığının aşırı artıp otlakların kuruması', 'Ormanların yanması', 'Deniz yolunun açılması'], 'Eylül-ekim aylarından sonra sıcaklıklar düşer ve otlaklar kar altında kalır; hayvanlar köy ahırlarına inmek zorundadır.'),
  ('Karadeniz kıyısındaki kıyı yolunun yağışlı dönemlerde sık sık kapanmasının nedeni nedir?', 'Heyelan ve taşkın olayları', ['Kuzeyden esen kum fırtınaları ve çölleşme', 'Buzla kaplanma', 'Tuzlanma'], 'Karadeniz kıyısında dik yamaçlar ve yoğun yağış, yol çevresinde heyelan ve taşkınlara yol açabilir.'),
  ('Doğu Karadeniz\'de yaylalar ile kıyı arasındaki mevsimlik hareketin ekonomik karşılığı nedir?', 'Yaylacılık ve büyükbaş hayvancılık', ['Madencilik ve tuz üretimi gibi sanayi faaliyetleri', 'Sera tarımı ve narenciye', 'Gemi inşa ve ticaret'], 'Yaz aylarında hayvanlar yaylalara çıkarılır; böylece otlaklardan yararlanılır ve süt ürünleri üretilir.'),
  ('Karadeniz kıyısında Samsun-Sinop arasında yer alan Kızılırmak Deltası\'nın oluşumunda hangi akarsu çökeltisi etkilidir?', 'Kızılırmak\'ın taşıdığı alüvyon', ['Yeşilırmak\'ın Çarşamba\'ya taşıdığı çökeltiler ve kum', 'Sakarya\'nın İzmit Körfezi\'ne bıraktığı çökeltiler', 'Çoruh\'un Gürcistan\'a taşıdığı çakıl ve alüvyon'], 'Kızılırmak Deltası, ırmağın İç Anadolu\'dan getirdiği alüvyonların Karadeniz kıyısında birikmesiyle oluşmuştur.'),
  ('Kıyı Ege\'de yaz aylarında nüfusun artması ve kışın azalması hangi tür yerleşmeler için tipiktir?', 'Turizm merkezi kıyı yerleşmeleri', ['Karadeniz\'in iç kesimdeki madencilik kasabaları', 'İç Anadolu\'nun tarım köyleri', 'Doğu Anadolu\'nun yayla köyleri'], 'Bodrum, Çeşme ve Marmaris gibi turizm yerleşmelerinde yazlık konut ve sezonluk çalışanlar nüfusu yazın artırır.'),
  ('Aydın ve Muğla\'da yazın kızılçam yangınlarının sıkça çıkmasının doğal nedeni nedir?', 'Sıcak ve kurak yaz ile rüzgâr', ['Bol yaz yağışı ve nem', 'Soğuk ve nemli kış', 'Sürekli sis ve düşük sıcaklık'], 'Akdeniz ikliminde yaz kuraktır ve sıcaklık yüksektir. Çam ormanları kolay tutuşur ve rüzgâr yangını hızla yayar.'),
  ('Manisa\'da UNESCO Somut Olmayan Kültürel Miras listesine alınan ve bitki özleriyle yapılan geleneksel şifalı ürün hangisidir?', 'Mesir macunu', ['Çam balı ve çiçek özleriyle yapılan ürün', 'Zeytinyağlı sabun ve defne ürünleri', 'Kuru incir ve hurma ezmesiyle yapılan tatlı'], 'Manisa\'da her yıl nevruz zamanı dağıtılan mesir macunu, birçok baharattan yapılan geleneksel bir üründür.'),
  ('Sakarya\'nın Karasu ilçesi hangi denize kıyısı olan yerleşmedir?', 'Karadeniz', ['Marmara Denizi, güneydeki kıyı', 'Ege Denizi, kuzey kıyıları', 'Akdeniz, doğu kıyıları'], 'Karasu, Sakarya\'nın Karadeniz kıyısındaki ilçesidir; Sakarya Nehri\'nin denize ulaştığı yere yakındır.'),
  ('Çanakkale\'nin Ezine ilçesi Türkiye\'de hangi ürünle ünlüdür?', 'Peynir', ['Zeytinyağlı sabun ve defne ürünü', 'Pamuklu tekstil ürünleri', 'Fındık ezmesi ve helva'], 'Ezine peyniri, Çanakkale\'nin Ezine ilçesinde üretilen, coğrafi işaretli bir koyun peynirdir.'),
  ('Muş\'ta Malazgirt Ovası hangi tarihî olayla anılır?', '1071 Malazgirt Meydan Muharebesi', ['1402 Ankara Savaşı', '1515 Çaldıran Savaşı', '1921 Sakarya Savaşı'], 'Malazgirt Ovası, Selçuklu Sultanı Alparslan\'ın 1071\'de Bizans ordusunu yendiği yerdir.'),
  ('Gaziantep\'te Fırat Nehri üzerinde yapılan Birecik Barajı\'nın en önemli kullanım amacı nedir?', 'Elektrik üretimi ve sulama', ['Deniz ulaşımı ve limanlar', 'Orman ürünleri taşımacılığı', 'Turizm ve yat marinası'], 'Birecik Barajı, Fırat\'ın akış gücünü elektrik üretiminde kullanır ve çevredeki tarım alanlarını sular.'),
  ('Gaziantep-Kilis çevresinde yer alan kuru yamaçlarda yetişen ve bölge mutfağında önemli olan ürün hangisidir?', 'Antep fıstığı', ['Çay yaprağı, Doğu Karadeniz\'de yetişen ürün', 'Hindistan cevizi, tropik kuşakta yetişen ürün', 'Şeker kamışı, subtropik kuşakta yetişen ürün'], 'Gaziantep ve çevresinde fıstık, zeytin ve üzüm kuru yamaçlarda yetişir.'),
  ('Büyükçekmece ve Terkos göllerinin İstanbul için önemi hangi ihtiyaçla ilgilidir?', 'İçme ve kullanma suyu', ['Elektrik üretimi için hidroelektrik', 'Balıkçılık ve balık ihracatı', 'Kış turizmi ve kayak'], 'Büyükçekmece ve Terkos, İstanbul\'un su ihtiyacını karşılayan önemli su kaynaklarındandır.'),
  ('Doğu Anadolu\'da akarsu vadilerinin dar ve derin olması hangi enerji türü yatırımlarını kolaylaştırır?', 'Hidroelektrik', ['Gelgit', 'Dalga enerjisi', 'Nükleer'], 'Dar ve derin vadiler baraj gövdesi kurmayı kolaylaştırır; eğim ve debi hidroelektrik için uygundur.'),
];
